7	
8	// A proper email: something, '@', something, '.', something — no whitespace. Matches the server
9	// (CreateClientLogic) and schema (V2) checks so the three layers agree on what is acceptable.
10	const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
11	
12	export function ClientsPage() {
13	  const [clients, setClients] = useState<Client[]>([]);
14	  const [name, setName] = useState('');
15	  const [email, setEmail] = useState('');
16	  const [emailError, setEmailError] = useState('');
17	  const [search, setSearch] = useState('');
18	  const [openClientId, setOpenClientId] = useState<number | null>(null);
19	
20	  async function load() {
21	    const res = await fetch('/api/clients');
22	    setClients(await res.json());
23	  }
24	
25	  useEffect(() => {
26	    void load();
27	  }, []);
28	
29	  async function onSubmit(e: React.FormEvent) {
30	    e.preventDefault();
31	
32	    // Every client needs a proper email — block the save and surface the error if it is missing or
33	    // malformed, so no row is created.
34	    if (!EMAIL.test(email.trim())) {
35	      setEmailError('A proper email address is required');
36	      return;
37	    }
38	    setEmailError('');
39	
