43	      body: JSON.stringify({ name, email: email.trim() }),
44	    });
45	    if (!res.ok) {
46	      setEmailError('A proper email address is required');
47	      return;
48	    }
49	    setName('');
50	    setEmail('');
51	    await load();
52	  }
